<section class="container page-section"><?php $this->load->view('commerce/environment'); ?><p><a href="<?php echo site_url('kelola/kredit?environment='.$environment); ?>">← Dompet kredit</a></p><h1 class="h2">Ledger — <?php echo html_escape($display_name); ?></h1><p>Saldo <?php echo $environment_label; ?>: <?php echo (int) $wallet['balance_credits']; ?> kredit <?php echo $environment_label; ?>. Kompensasi voucher belum terpakai menambah mutasi baru, tidak menghapus debit awal. Bukan refund uang ke rekening.</p>
<h2 class="h4">Mutasi</h2><div class="row g-3 mb-4"><?php foreach ($wallet['entries'] as $e): ?><div class="col-md-6"><article class="feature-card"><strong>#<?php echo (int) $e['id']; ?> · <?php echo (int) $e['delta_credits']; ?> kredit</strong><p><?php echo html_escape($e['note'] ?: $e['entry_type']); ?></p><small><?php echo html_escape(study_format_datetime($e['created_at'])); ?></small></article></div><?php endforeach; ?><?php if ( ! $wallet['entries']): ?><p>Belum ada mutasi pada halaman ini.</p><?php endif; ?></div>
<h2 class="h4">Pembelian & kompensasi</h2><div class="row g-3 mb-4"><?php foreach ($purchases as $p): ?><?php $s = json_decode($p['snapshot_json'], TRUE); ?><div class="col-md-6"><article class="feature-card"><h3 class="h5">#<?php echo (int) $p['id']; ?> · <?php echo html_escape($s['title']); ?></h3><p><?php echo html_escape($p['status']); ?></p><?php if ($s['kind'] === 'voucher' && $p['status'] === 'available'): ?><details><summary>Kompensasi voucher belum terpakai</summary><?php echo form_open('kelola/voucher/'.(int) $p['id'].'/kompensasi'); ?><div class="my-3"><label class="form-label" for="reason-<?php echo (int) $p['id']; ?>">Alasan (10–300 karakter)</label><textarea class="form-control" id="reason-<?php echo (int) $p['id']; ?>" name="reason" minlength="10" maxlength="300" required></textarea></div><div class="mb-3"><label class="form-label" for="password-<?php echo (int) $p['id']; ?>">Kata sandi Superadmin</label><input class="form-control" type="password" autocomplete="current-password" id="password-<?php echo (int) $p['id']; ?>" name="password" required></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" id="confirm-<?php echo (int) $p['id']; ?>" name="confirm" value="1" required><label class="form-check-label" for="confirm-<?php echo (int) $p['id']; ?>">Kembalikan <?php echo (int) $s['price']; ?> kredit <?php echo $environment_label; ?> dan nonaktifkan voucher ini.</label></div><button class="btn btn-outline-danger">Catat kompensasi</button><?php echo form_close(); ?></details><?php endif; ?></article></div><?php endforeach; ?><?php if ( ! $purchases): ?><p>Belum ada pembelian pada halaman ini.</p><?php endif; ?></div>
<nav aria-label="Halaman ledger"><?php if ($page > 1): ?><a href="<?php echo site_url('kelola/kredit/'.(int) $owner.'?environment='.$environment.'&halaman='.($page - 1)); ?>">Sebelumnya</a><?php endif; ?> · Halaman <?php echo (int) $page; ?> <?php if (count($purchases) === 20 || $page * 20 < $wallet['total']): ?><a href="<?php echo site_url('kelola/kredit/'.(int) $owner.'?environment='.$environment.'&halaman='.($page + 1)); ?>">Berikutnya</a><?php endif; ?></nav></section>
